$TestArchivesPath = 'artifacts/tests'
$TestPackagesPath = 'artifacts/test-packages'
$DefaultTimeoutSeconds = 1800

# The exit codes of Microsoft.Testing.Platform that this script reads. See https://aka.ms/testingplatform/exitcodes.
$FailedTestsExitCode = 2
$ZeroTestsExitCode = 8

# The number of lines of each output file that is written when an application fails and its output is not shown.
$OutputTailLineCount = 100

# TeamCity reads a service message up to the first unescaped delimiter, so an unescaped value silently truncates or
# corrupts the report. The vertical bar is replaced first: doing it later would double the bars introduced by the other
# replacements.
function ConvertTo-TeamCityValue([string]$value)
{
    if ($null -eq $value)
    {
        return ''
    }

    $escaped = $value.Replace('|', '||')
    $escaped = $escaped.Replace("'", "|'")
    $escaped = $escaped.Replace('[', '|[')
    $escaped = $escaped.Replace(']', '|]')
    $escaped = $escaped.Replace("`r", '|r')
    $escaped = $escaped.Replace("`n", '|n')

    return $escaped
}

function Write-ServiceMessage([string]$name, [hashtable]$attributes)
{
    if ($NoTeamCity)
    {
        return
    }

    $pairs = $attributes.Keys | Sort-Object | ForEach-Object {
        "$_='$( ConvertTo-TeamCityValue $attributes[$_] )'"
    }

    Write-Host "##teamcity[$name $( $pairs -join ' ' )]"
}

function Get-HostPlatform
{
    $os = if ($IsWindows) { 'win' } elseif ($IsLinux) { 'linux' } elseif ($IsMacOS) { 'osx' } else { $null }

    $arch = switch ([System.Runtime.InteropServices.RuntimeInformation]::OSArchitecture)
    {
        'X64' { 'x64' }
        'Arm64' { 'arm64' }
        default { $null }
    }

    if (-not $os -or -not $arch)
    {
        throw "This host has an unsupported platform: $( [System.Runtime.InteropServices.RuntimeInformation]::OSDescription ), $( [System.Runtime.InteropServices.RuntimeInformation]::OSArchitecture )."
    }

    return "$os-$arch"
}

# Reads test.psd1 from the archive without extracting the rest of it. An archive that does not apply to the platform is
# never extracted, and some archives are hundreds of megabytes.
function Read-ArchiveManifest([string]$archivePath)
{
    $temporaryFile = Join-Path ([System.IO.Path]::GetTempPath()) "test-$( [System.Guid]::NewGuid().ToString('n') ).psd1"

    try
    {
        $archive = [System.IO.Compression.ZipFile]::OpenRead($archivePath)

        try
        {
            $entry = $archive.GetEntry('test.psd1')

            if (-not $entry)
            {
                return @{ Error = 'The archive has no test.psd1 at its root.' }
            }

            [System.IO.Compression.ZipFileExtensions]::ExtractToFile($entry, $temporaryFile, $true)
        }
        finally
        {
            $archive.Dispose()
        }

        $manifest = Import-PowerShellDataFile -LiteralPath $temporaryFile -ErrorAction Stop
    }
    catch
    {
        return @{ Error = "The manifest cannot be read: $( $_.Exception.Message )" }
    }
    finally
    {
        Remove-Item -LiteralPath $temporaryFile -Force -ErrorAction SilentlyContinue
    }

    if (-not $manifest.Platforms)
    {
        return @{ Error = 'The manifest does not declare Platforms.' }
    }

    if (-not $manifest.Entry)
    {
        return @{ Error = 'The manifest does not declare Entry.' }
    }

    $kind = if ($manifest.Kind) { $manifest.Kind } else { 'mtp' }

    if ($kind -notin 'mtp', 'exe', 'ps1')
    {
        return @{ Error = "The manifest declares the unknown Kind '$kind'." }
    }

    return @{
        Name = $manifest.Name
        TargetFramework = $manifest.TargetFramework
        Kind = $kind
        Entry = $manifest.Entry
        Platforms = @($manifest.Platforms)
        Extensions = @($manifest.Extensions)
        Tags = @($manifest.Tags)
        TimeoutSeconds = if ($manifest.TimeoutSeconds) { [int]$manifest.TimeoutSeconds } else { $DefaultTimeoutSeconds }
        RunAlone = [bool]$manifest.RunAlone
        Skip = $manifest.Skip
        Arguments = @($manifest.Arguments)
        ReportType = $manifest.ReportType
        ReportFile = $manifest.ReportFile
        Prepare = $manifest.Prepare
        Artifacts = @($manifest.Artifacts)
        Packages = @($manifest.Packages | Where-Object { $_ })
    }
}

# Finds a package that the manifest of an archive lists, and returns where its files are: the directory of the package in
# the NuGet cache, or a nupkg. A package that cannot be found is returned with an Error, which fails the archives that need
# it and not the others.
function Get-Package([hashtable]$package)
{
    $id = $package.Id
    $version = $package.Version
    $name = "$id.$version.nupkg"

    # The NuGet cache holds the extracted package. NuGet writes the .sha512 file after the other files, so its presence
    # means that the extraction completed, and an interrupted extraction is not used.
    $cacheRoot = if ($env:NUGET_PACKAGES) { $env:NUGET_PACKAGES } else { Join-Path ([Environment]::GetFolderPath('UserProfile')) '.nuget' 'packages' }
    $cacheDirectory = Join-Path $cacheRoot $id $version
    $cacheHash = Join-Path $cacheDirectory "$name.sha512"

    if (Test-Path -LiteralPath $cacheHash)
    {
        return @{ Directory = $cacheDirectory }
    }

    if (-not $package.Url)
    {
        # The build configuration downloads the package from the build that published it, under its original file name, to
        # a directory per producer. The file name is compared without case, because the manifest has the identifier and the
        # version in lower case.
        $file = if (Test-Path -LiteralPath $PackagesPath -PathType Container)
        {
            Get-ChildItem -LiteralPath $PackagesPath -Recurse -File -Filter '*.nupkg' |
                    Where-Object { $_.Name -ieq $name } |
                    Select-Object -First 1 -ExpandProperty FullName
        }

        if (-not $file)
        {
            return @{ Error = "The package '$id' $version is not in '$PackagesPath'. The build configuration downloads the packages that 'Build.ps1 generate-scripts' listed for its archives in test-archives.txt, from the builds that publish them; run 'Build.ps1 generate-scripts' if that list is out of date." }
        }
    }
    else
    {
        $file = Join-Path $Path 'run' 'packages' $name

        if (-not (Test-Path -LiteralPath $file))
        {
            New-Item -ItemType Directory -Path (Split-Path $file) -Force | Out-Null
            $temporaryFile = "$file.download"
            Write-Host "Downloading $( $package.Url )." -ForegroundColor DarkGray

            try
            {
                Invoke-WebRequest -Uri $package.Url -OutFile $temporaryFile -MaximumRetryCount 4 -RetryIntervalSec 5 -ErrorAction Stop
            }
            catch
            {
                Remove-Item -LiteralPath $temporaryFile -Force -ErrorAction SilentlyContinue

                return @{ Error = "The package '$id' $version cannot be downloaded from $( $package.Url ): $( $_.Exception.Message )" }
            }

            Move-Item -LiteralPath $temporaryFile -Destination $file -Force
        }
    }

    return @{ File = $file }
}

# Copies the files that the application takes from packages to their places in its directory.
function Install-Packages([hashtable]$run)
{
    foreach ($package in $run.Manifest.Packages)
    {
        $source = $script:Packages["$( $package.Id )/$( $package.Version )"]

        if ($source.Error)
        {
            throw $source.Error
        }

        $files = @($package.Files)

        if ($source.Directory)
        {
            foreach ($file in $files)
            {
                $target = Join-Path $run.Directory $file.Target
                New-Item -ItemType Directory -Path (Split-Path $target) -Force | Out-Null
                Copy-Item -LiteralPath (Join-Path $source.Directory $file.Path) -Destination $target -Force
            }

            continue
        }

        $archive = [System.IO.Compression.ZipFile]::OpenRead($source.File)

        try
        {
            # The entries of a nupkg have escaped names, such as %2B for a plus sign.
            $entries = @{ }

            foreach ($entry in $archive.Entries)
            {
                $entries[[System.Uri]::UnescapeDataString($entry.FullName)] = $entry
            }

            foreach ($file in $files)
            {
                $entry = $entries[$file.Path]

                if (-not $entry)
                {
                    throw "The package '$( $package.Id )' $( $package.Version ) has no '$( $file.Path )', which the manifest lists."
                }

                $target = Join-Path $run.Directory $file.Target
                New-Item -ItemType Directory -Path (Split-Path $target) -Force | Out-Null
                [System.IO.Compression.ZipFileExtensions]::ExtractToFile($entry, $target, $true)
            }
        }
        finally
        {
            $archive.Dispose()
        }
    }
}

# Tells why an archive does not run, or returns $null when it runs.
function Get-ExclusionReason([hashtable]$manifest)
{
    if ($manifest.Skip)
    {
        return "skipped: $( $manifest.Skip )"
    }

    if ($manifest.Platforms -notcontains $Platform)
    {
        return "not applicable: the archive declares $( $manifest.Platforms -join ', ' ) and not $Platform"
    }

    if ($Tags -and -not ($manifest.Tags | Where-Object { $Tags -contains $_ }))
    {
        return "not selected: the archive has none of the tags $( $Tags -join ', ' )"
    }

    if ($ExcludeTags)
    {
        $excluded = @($manifest.Tags | Where-Object { $ExcludeTags -contains $_ })

        if ($excluded)
        {
            return "not selected: the archive has the tag $( $excluded -join ', ' )"
        }
    }

    return $null
}

# Tells whether the target framework is one of the .NET Framework, whose moniker has no dot (net48), unlike that of
# .NET (net10.0).
function Test-NetFramework([string]$targetFramework)
{
    return $targetFramework -match '^net\d+$'
}

# The .NET runtimes of this host, by framework name, from 'dotnet --list-runtimes'.
function Get-InstalledRuntimes([string]$dotnet)
{
    $runtimes = @{}

    foreach ($line in & $dotnet --list-runtimes)
    {
        if ($line -match '^(\S+)\s+(\S+)\s+\[')
        {
            if (-not $runtimes.ContainsKey($Matches[1]))
            {
                $runtimes[$Matches[1]] = @()
            }

            $runtimes[$Matches[1]] += $Matches[2]
        }
    }

    return $runtimes
}

# Gets the numeric part of a runtime version, without the prerelease label: 11.0.0-rc.1.2 becomes 11.0.0.
function ConvertTo-NumericVersion([string]$version)
{
    return [Version]($version -replace '-.*$', '')
}

# Tells why the runtimes of this host cannot run a .NET application, or returns $null when they can. The frameworks
# come from the runtimeconfig.json of the application, which is what the .NET host reads. Without this check, the
# application would fail with the message of the host, which does not say that the agent lacks a runtime.
function Get-MissingRuntime([string]$entryPath, [hashtable]$installedRuntimes)
{
    # DOTNET_ROLL_FORWARD changes the rule that the host applies, so the host decides alone.
    if ($env:DOTNET_ROLL_FORWARD)
    {
        return $null
    }

    $configurationPath = [System.IO.Path]::ChangeExtension($entryPath, '.runtimeconfig.json')

    if (-not (Test-Path -LiteralPath $configurationPath))
    {
        return $null
    }

    $options = (Get-Content -LiteralPath $configurationPath -Raw | ConvertFrom-Json).runtimeOptions
    $frameworks = @($options.framework) + @($options.frameworks) | Where-Object { $_ }
    $rollForward = $options.rollForward

    foreach ($framework in $frameworks)
    {
        $requested = ConvertTo-NumericVersion $framework.version

        $candidates = @($installedRuntimes[$framework.name] | Where-Object { $_ } | ForEach-Object { ConvertTo-NumericVersion $_ })

        $compatible = $candidates | Where-Object {
            if ($rollForward -in 'Major', 'LatestMajor')
            {
                $_ -ge $requested
            }
            else
            {
                $_.Major -eq $requested.Major -and $_ -ge $requested
            }
        }

        if (-not $compatible)
        {
            $installed = if ($candidates) { $installedRuntimes[$framework.name] -join ', ' } else { 'none' }

            return "The application needs $( $framework.name ) $( $framework.version ), and this host has $installed."
        }
    }

    return $null
}

# Quotes one argument by the rules that the .NET process launcher and the C runtime of Windows both parse: backslashes
# are literal except before a quote, where they are doubled.
function ConvertTo-CommandLineArgument([string]$argument)
{
    if ($argument -and $argument -notmatch '[\s"]')
    {
        return $argument
    }

    $builder = [System.Text.StringBuilder]::new('"')
    $backslashes = 0

    foreach ($character in $argument.ToCharArray())
    {
        if ($character -eq '\')
        {
            $backslashes++
            continue
        }

        if ($character -eq '"')
        {
            [void]$builder.Append([char]'\', 2 * $backslashes + 1)
        }
        elseif ($backslashes -gt 0)
        {
            [void]$builder.Append([char]'\', $backslashes)
        }

        $backslashes = 0
        [void]$builder.Append($character)
    }

    [void]$builder.Append([char]'\', 2 * $backslashes)
    [void]$builder.Append('"')

    return $builder.ToString()
}

# Builds the command line of one application.
function Get-ApplicationCommand([hashtable]$run, [string]$dotnet)
{
    $manifest = $run.Manifest
    $entryPath = Join-Path $run.Directory $manifest.Entry
    $arguments = @()

    if ($manifest.Kind -eq 'mtp')
    {
        $arguments += '--results-directory', $run.ResultsDirectory

        if ($manifest.Extensions -contains 'Microsoft.Testing.Extensions.TrxReport')
        {
            # A short name: the directory already names the archive, and a .NET Framework application cannot write a
            # report into a path of more than 260 characters.
            $arguments += '--report-trx', '--report-trx-filename', 'report.trx'
        }

        # The dump is taken before the application is killed, so that a hung run leaves a dump of the process.
        if ($manifest.Extensions -contains 'Microsoft.Testing.Extensions.HangDump')
        {
            $hangDumpSeconds = [Math]::Max([int]($manifest.TimeoutSeconds * 0.8), $manifest.TimeoutSeconds - 300)
            $arguments += '--hangdump', '--hangdump-timeout', "$( $hangDumpSeconds )s"
        }

        # The crash dump extension supports .NET only.
        if ($manifest.Extensions -contains 'Microsoft.Testing.Extensions.CrashDump' -and -not (Test-NetFramework $manifest.TargetFramework))
        {
            $arguments += '--crashdump'
        }

        if ($ApplicationArguments)
        {
            $arguments += '--ignore-exit-code', "$ZeroTestsExitCode"
        }
    }
    elseif ($manifest.Kind -eq 'ps1')
    {
        # A script that runs the tests itself. It is told the platform and where to write its results, as the Docker tests
        # are told the platform.
        $arguments += '-Platform', $Platform, '-ResultsDirectory', $run.ResultsDirectory
    }
    else
    {
        $arguments += $manifest.Arguments | Where-Object { $_ } | ForEach-Object { $_.Replace('{ResultsDirectory}', $run.ResultsDirectory) }
    }

    $arguments += $ApplicationArguments | Where-Object { $_ }

    if ($manifest.Kind -eq 'ps1')
    {
        # The PowerShell that runs this script, so that the application does not depend on what the PATH finds.
        $powershell = (Get-Process -Id $PID).Path

        return @{ FilePath = $powershell; Arguments = @('-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-File', $entryPath) + $arguments }
    }

    if ($manifest.Entry -like '*.dll')
    {
        return @{ FilePath = $dotnet; Arguments = @('exec', $entryPath) + $arguments }
    }

    return @{ FilePath = $entryPath; Arguments = $arguments }
}

# Kills a process and everything it started. Stop-Process alone does not: it terminates the one process, and the
# children it spawned are reparented rather than killed.
function Stop-ProcessTree([int]$processId)
{
    $children = if ($IsWindows)
    {
        @( Get-CimInstance Win32_Process -Filter "ParentProcessId = $processId" -ErrorAction SilentlyContinue |
                ForEach-Object { [int]$_.ProcessId } )
    }
    else
    {
        @( & pgrep -P $processId 2>$null | ForEach-Object { [int]$_ } )
    }

    foreach ($child in $children)
    {
        Stop-ProcessTree $child
    }

    Stop-Process -Id $processId -Force -ErrorAction SilentlyContinue
}

# Copies whatever has been appended to the redirected output files since the last call. FileShare.ReadWrite is
# required: the application still holds these files open.
function Copy-NewOutput([hashtable]$positions)
{
    foreach ($file in @($positions.Keys))
    {
        if (-not (Test-Path -LiteralPath $file))
        {
            continue
        }

        $stream = $null

        try
        {
            $stream = [System.IO.File]::Open($file, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)

            if ($stream.Length -gt $positions[$file])
            {
                $stream.Position = $positions[$file]
                $reader = [System.IO.StreamReader]::new($stream)
                $text = $reader.ReadToEnd()
                $positions[$file] = $stream.Position

                if ($text)
                {
                    Write-Host $text -NoNewline
                }
            }
        }
        catch
        {
            # A transient sharing failure only delays the output to the next pass.
        }
        finally
        {
            if ($stream)
            {
                $stream.Dispose()
            }
        }
    }
}

# Runs the prepare script of an archive, which its manifest names, and returns the environment variables that the script
# returns for the application. The script receives the root of the repository, under which the artifacts that the
# manifest declares were downloaded, and the directory of the extracted application. It runs in this process, in the
# directory of the application; an exception or a non-zero exit code fails the archive.
function Invoke-PrepareScript([hashtable]$run)
{
    $environment = @{}

    if (-not $run.Manifest.Prepare)
    {
        return $environment
    }

    $script = Join-Path $run.Directory $run.Manifest.Prepare

    if (-not (Test-Path -LiteralPath $script))
    {
        throw "The archive has no '$( $run.Manifest.Prepare )', which its manifest names as the prepare script."
    }

    foreach ($artifact in $run.Manifest.Artifacts)
    {
        if (-not (Get-ChildItem -Path (Join-Path $repositoryRoot $artifact) -File -ErrorAction SilentlyContinue))
        {
            throw "The artifact '$artifact', which the manifest declares, is not in '$repositoryRoot'. Download it with the archive."
        }
    }

    Write-Host "Preparing $( $run.Key ): $( $run.Manifest.Prepare )" -ForegroundColor Green

    Push-Location -LiteralPath $run.Directory

    try
    {
        $global:LASTEXITCODE = 0
        $output = @( & $script -RepositoryRoot $repositoryRoot -ApplicationDirectory $run.Directory )

        if ($LASTEXITCODE -ne 0)
        {
            throw "The prepare script failed with exit code $LASTEXITCODE."
        }
    }
    finally
    {
        Pop-Location
    }

    foreach ($item in $output)
    {
        if ($item -is [System.Collections.IDictionary])
        {
            foreach ($key in $item.Keys)
            {
                $environment[[string]$key] = [string]$item[$key]
            }
        }
        elseif ($null -ne $item)
        {
            Write-Host $item
        }
    }

    return $environment
}

# Extracts the archive and starts its application. The output goes to files, so that applications running at the same
# time do not interleave their lines.
function Start-TestRun([hashtable]$run, [string]$dotnet)
{
    Remove-Item -LiteralPath $run.Directory -Recurse -Force -ErrorAction SilentlyContinue
    Remove-Item -LiteralPath $run.ResultsDirectory -Recurse -Force -ErrorAction SilentlyContinue
    [System.IO.Compression.ZipFile]::ExtractToDirectory($run.Archive, $run.Directory, $true)
    Install-Packages $run
    New-Item -ItemType Directory -Path $run.ResultsDirectory -Force | Out-Null

    $entryPath = Join-Path $run.Directory $run.Manifest.Entry

    if (-not (Test-Path -LiteralPath $entryPath))
    {
        throw "The archive has no '$( $run.Manifest.Entry )', which its manifest names as the entry point."
    }

    if ($run.Manifest.Entry -like '*.dll')
    {
        $missingRuntime = Get-MissingRuntime $entryPath $run.InstalledRuntimes

        if ($missingRuntime)
        {
            throw $missingRuntime
        }
    }
    elseif (-not $IsWindows)
    {
        # A zip file written on Windows does not keep the permission to execute.
        & chmod +x $entryPath
    }

    # A .NET Framework application run from a deep directory failed to load an assembly that was present, with a
    # FileNotFoundException that does not mention the path: the longest path was 257 characters, and the same files ran
    # from a path of 223. The limit of 260 characters of Windows is the likely cause, so the path is named in advance.
    if (Test-NetFramework $run.Manifest.TargetFramework)
    {
        $longestPath = Get-ChildItem -LiteralPath $run.Directory -Recurse -File |
                ForEach-Object { $_.FullName.Length } |
                Measure-Object -Maximum

        if ($longestPath.Maximum -ge 240)
        {
            Write-Host "$( $run.Key ): the longest path of the application is $( $longestPath.Maximum ) characters. A .NET Framework application can fail to load an assembly from a path close to 260 characters; use a shorter -Path if it does." -ForegroundColor Yellow
        }
    }

    $environment = Invoke-PrepareScript $run

    $command = Get-ApplicationCommand $run $dotnet
    $run.StdOut = Join-Path $run.ResultsDirectory 'stdout.log'
    $run.StdErr = Join-Path $run.ResultsDirectory 'stderr.log'

    Write-Host "Starting $( $run.Key ): $( $command.FilePath ) $( $command.Arguments -join ' ' )" -ForegroundColor Green

    $startArguments = @{
        FilePath = $command.FilePath
        WorkingDirectory = $run.Directory
        PassThru = $true
        NoNewWindow = $true
        RedirectStandardOutput = $run.StdOut
        RedirectStandardError = $run.StdErr
    }

    if ($environment.Count -gt 0)
    {
        $startArguments.Environment = $environment
    }

    # Start-Process refuses an empty argument list.
    if ($command.Arguments)
    {
        $startArguments.ArgumentList = ($command.Arguments | ForEach-Object { ConvertTo-CommandLineArgument $_ }) -join ' '
    }

    $run.Process = Start-Process @startArguments

    # The process object of Start-Process reports no exit code unless its handle was opened while the process ran.
    $null = $run.Process.Handle

    $run.Positions = @{ $run.StdOut = [long]0; $run.StdErr = [long]0 }
    $run.Stopwatch = [System.Diagnostics.Stopwatch]::StartNew()
    $run.Deadline = [DateTime]::UtcNow.AddSeconds($run.Manifest.TimeoutSeconds)
}

# Gives each data row of a theory its own name in a TRX report. The report names a row in the 'name' attribute of its
# UnitTest element, for example 'Namespace.Class.Method(value: 1)', but its TestMethod element carries the name of the
# method only. The MSTest importer of TeamCity names a test from TestMethod, so it reports every row of a theory as one
# test that ran several times. This writes the name of the row, without the class, into TestMethod.
function Set-TrxDataRowNames([string]$path)
{
    $document = [System.Xml.Linq.XDocument]::Load($path, [System.Xml.Linq.LoadOptions]::PreserveWhitespace)
    $namespace = $document.Root.Name.Namespace
    $renamed = 0

    foreach ($unitTest in $document.Descendants($namespace.GetName('UnitTest')))
    {
        $testMethod = $unitTest.Element($namespace.GetName('TestMethod'))
        $testName = $unitTest.Attribute('name')

        if (-not $testMethod -or -not $testName -or -not $testMethod.Attribute('className'))
        {
            continue
        }

        $testName = $testName.Value
        $className = $testMethod.Attribute('className').Value

        $rowName = if ($testName.StartsWith("$className.", [System.StringComparison]::Ordinal))
        {
            $testName.Substring($className.Length + 1)
        }
        else
        {
            $testName
        }

        $methodName = $testMethod.Attribute('name')

        if (-not $methodName -or $rowName -ne $methodName.Value)
        {
            $testMethod.SetAttributeValue('name', $rowName)
            $renamed++
        }
    }

    if ($renamed -gt 0)
    {
        $document.Save($path, [System.Xml.Linq.SaveOptions]::DisableFormatting)
    }
}

# Reports the result of a finished application and returns the reason it failed, or $null when it passed.
function Complete-TestRun([hashtable]$run, [bool]$timedOut)
{
    $manifest = $run.Manifest

    if ($timedOut)
    {
        # The whole tree: 'dotnet exec' is the parent of nothing today, but an application may start processes of its
        # own, and killing only the one that was waited on would leave them running.
        Stop-ProcessTree $run.Process.Id
        $run.Process.WaitForExit(30 * 1000) | Out-Null
    }
    else
    {
        # The parameterless overload also waits for the redirected streams to be flushed.
        $run.Process.WaitForExit()
    }

    $run.Stopwatch.Stop()

    if (-not $ShowOutput)
    {
        # The output stays in the files of the results directory.
    }
    elseif (-not $run.Live)
    {
        Write-ServiceMessage 'blockOpened' @{ name = $run.Key }

        foreach ($file in $run.StdOut, $run.StdErr)
        {
            $content = Get-Content -LiteralPath $file -Raw -ErrorAction SilentlyContinue

            if ($content)
            {
                Write-Host $content -NoNewline
            }
        }

        Write-ServiceMessage 'blockClosed' @{ name = $run.Key }
    }
    else
    {
        Copy-NewOutput $run.Positions
    }

    # The report is imported even when the application failed, so that TeamCity shows which tests failed. A report is
    # complete once the application has exited, and TeamCity reads it as soon as it is told about it.
    $reports = if ($manifest.Kind -eq 'mtp')
    {
        @( Get-ChildItem -LiteralPath $run.ResultsDirectory -Filter '*.trx' -Recurse -File | ForEach-Object { $_.FullName } )
    }
    elseif ($manifest.ReportFile)
    {
        # The file name can contain wildcards, for an application that writes one report per run, such as per platform.
        @( Get-ChildItem -Path $manifest.ReportFile.Replace('{ResultsDirectory}', $run.ResultsDirectory) -File -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName } )
    }
    else
    {
        @()
    }

    foreach ($report in $reports)
    {
        if ($manifest.Kind -eq 'mtp')
        {
            try
            {
                Set-TrxDataRowNames $report
            }
            catch
            {
                Write-Host "The data rows of '$report' cannot be named: $( $_.Exception.Message )" -ForegroundColor Yellow
            }
        }

        $type = if ($manifest.Kind -eq 'mtp') { 'mstest' } else { $manifest.ReportType }
        Write-ServiceMessage 'importData' @{ type = $type; path = $report; flowId = $run.Key }
    }

    $duration = $run.Stopwatch.Elapsed.ToString('hh\:mm\:ss')

    if ($timedOut)
    {
        return "the application exceeded its timeout of $( $manifest.TimeoutSeconds ) seconds and was killed"
    }

    $exitCode = $run.Process.ExitCode

    if ($exitCode -ne 0)
    {
        return "the application failed with exit code $exitCode after $duration"
    }

    if (-not $reports -and ($manifest.ReportFile -or $manifest.Extensions -contains 'Microsoft.Testing.Extensions.TrxReport'))
    {
        return 'the application succeeded but wrote no report'
    }

    Write-Host "$( $run.Key ) passed in $duration." -ForegroundColor Green

    return $null
}

# Writes the last lines of the output files of an application whose output was not shown.
function Write-OutputTail([hashtable]$run)
{
    Write-ServiceMessage 'blockOpened' @{ name = "$( $run.Key ) output" }

    foreach ($file in $run.StdOut, $run.StdErr)
    {
        $lines = @( Get-Content -LiteralPath $file -Tail $OutputTailLineCount -ErrorAction SilentlyContinue )

        if ($lines.Count -gt 0)
        {
            Write-Host "Last $( $lines.Count ) lines of $file :"
            $lines | ForEach-Object { Write-Host $_ }
        }
    }

    Write-ServiceMessage 'blockClosed' @{ name = "$( $run.Key ) output" }
}

# Runs the given archives, at most $maxParallel at a time, and returns the failed ones.
function Invoke-TestRuns([hashtable[]]$runs, [int]$maxParallel, [string]$dotnet)
{
    $failed = @()
    $queue = [System.Collections.Generic.Queue[hashtable]]::new()
    $runs | ForEach-Object { $queue.Enqueue($_) }
    $running = [System.Collections.Generic.List[hashtable]]::new()

    # The output of an application that runs alone is shown as it arrives, so that a long run is not indistinguishable
    # from a hung one. The output of applications that run at the same time is shown in one block when each finishes.
    # Without -ShowOutput, neither is shown.
    $live = $ShowOutput -and $maxParallel -eq 1

    while ($queue.Count -gt 0 -or $running.Count -gt 0)
    {
        while ($queue.Count -gt 0 -and $running.Count -lt $maxParallel)
        {
            $run = $queue.Dequeue()
            $run.Live = $live

            try
            {
                Start-TestRun $run $dotnet
                $running.Add($run)
            }
            catch
            {
                $message = "$( $run.Key ): $( $_.Exception.Message )"
                Write-Host $message -ForegroundColor Red
                Write-ServiceMessage 'buildProblem' @{ description = $message }
                $failed += $run.Key
            }
        }

        Start-Sleep -Milliseconds 500

        foreach ($run in @($running))
        {
            if ($run.Live)
            {
                Copy-NewOutput $run.Positions
            }

            $timedOut = -not $run.Process.HasExited -and [DateTime]::UtcNow -gt $run.Deadline

            if (-not $run.Process.HasExited -and -not $timedOut)
            {
                continue
            }

            $running.Remove($run) | Out-Null

            try
            {
                $reason = Complete-TestRun $run $timedOut
            }
            catch
            {
                $reason = "the runner failed: $( $_.Exception.Message )"
            }

            if ($reason)
            {
                if (-not $ShowOutput)
                {
                    Write-OutputTail $run
                }

                $message = "$( $run.Key ): $reason."
                Write-Host $message -ForegroundColor Red

                # Failed tests fail the build through the imported report. Anything else, such as a crash, a timeout
                # or a missing report, would leave the build green unless it is reported as a problem.
                if ($timedOut -or $run.Process.ExitCode -ne $FailedTestsExitCode)
                {
                    Write-ServiceMessage 'buildProblem' @{ description = $message }
                }

                $failed += $run.Key
            }
        }
    }

    return $failed
}

Add-Type -AssemblyName System.IO.Compression.FileSystem
Add-Type -AssemblyName System.Xml.Linq

Push-Location
try
{
    # This script lives in the engineering directory, not at the root, so everything it addresses relative to the
    # repository is resolved from the parent.
    $repositoryRoot = ( Resolve-Path ( Join-Path $PSScriptRoot '..' ) ).Path
    Set-Location $repositoryRoot

    if (-not $env:TEAMCITY_VERSION -and -not $env:IS_TEAMCITY_AGENT)
    {
        $NoTeamCity = $true
    }

    if ($NoTeamCity)
    {
        $ShowOutput = $true
    }

    if (-not $Path)
    {
        $Path = $TestArchivesPath
    }

    if (-not $ResultsPath)
    {
        $ResultsPath = $TestResultsPath
    }

    if (-not $PackagesPath)
    {
        $PackagesPath = $TestPackagesPath
    }

    $Path = [System.IO.Path]::GetFullPath($Path, $repositoryRoot)
    $PackagesPath = [System.IO.Path]::GetFullPath($PackagesPath, $repositoryRoot)
    $ResultsPath = [System.IO.Path]::GetFullPath($ResultsPath, $repositoryRoot)

    if (-not $Platform)
    {
        $Platform = Get-HostPlatform
    }

    # A build step passes its arguments as text, and pwsh -File passes 'a,b' to an array parameter as one string, so a list
    # can arrive as one comma-separated value.
    $Name = @( $Name | ForEach-Object { $_ -split ',' } | Where-Object { $_ } )
    $Tags = @( $Tags | ForEach-Object { $_ -split ',' } | Where-Object { $_ } )
    $ExcludeTags = @( $ExcludeTags | ForEach-Object { $_ -split ',' } | Where-Object { $_ } )

    if ($MaxParallel -le 0)
    {
        $MaxParallel = [Math]::Max(1, [int][Math]::Floor([Environment]::ProcessorCount / 4))
    }

    $env:TESTINGPLATFORM_TELEMETRY_OPTOUT = '1'
    $env:DOTNET_CLI_TELEMETRY_OPTOUT = '1'
    $env:DOTNET_NOLOGO = '1'

    if (-not (Test-Path -LiteralPath $Path -PathType Container))
    {
        Write-Host "The directory of the test archives, '$Path', does not exist. Build the product first." -ForegroundColor Red
        exit 1
    }

    $archives = @( Get-ChildItem -LiteralPath $Path -Filter '*.zip' -File | Sort-Object Name )

    if ($Name)
    {
        $archives = @( $archives | Where-Object { $archive = $_; $Name | Where-Object { $archive.BaseName -like $_ } } )
    }

    if (-not $archives)
    {
        Write-Host "There is no test archive in '$Path'$( if ($Name) { " whose name matches $( $Name -join ', ' )" } )." -ForegroundColor Red
        exit 1
    }

    Write-Host "Platform: $Platform. Archives: $Path." -ForegroundColor Cyan

    $runs = @()
    $failed = @()
    $ignored = 0

    foreach ($archive in $archives)
    {
        $key = $archive.BaseName
        $manifest = Read-ArchiveManifest $archive.FullName

        if ($manifest.Error)
        {
            Write-Host "$key : $( $manifest.Error )" -ForegroundColor Red
            Write-ServiceMessage 'buildProblem' @{ description = "$key : $( $manifest.Error )" }
            $failed += $key
            continue
        }

        $reason = Get-ExclusionReason $manifest

        if ($reason)
        {
            Write-Host "$key : $reason." -ForegroundColor DarkGray
            $ignored++
            continue
        }

        if ($List)
        {
            Write-Host "$key : runs$( if ($manifest.RunAlone) { ' alone' } )." -ForegroundColor Green
        }

        $runs += @{
            Key = $key
            Archive = $archive.FullName
            Manifest = $manifest
            Directory = Join-Path $Path 'run' $key
            ResultsDirectory = Join-Path $ResultsPath $key
        }
    }

    if ($List)
    {
        exit $( if ($failed) { 1 } else { 0 } )
    }

    # Nothing to run is a failure. A test run that reports success without having run a test is worse than one that
    # fails, because nobody looks at it again: a build configuration given the wrong archives, or a tag with a typo,
    # would be green forever.
    if (-not $runs -and -not $failed)
    {
        Write-Host "None of the $( $archives.Count ) test archive(s) applies to $Platform$( if ($Tags -or $ExcludeTags) { ' and to the tags' } )." -ForegroundColor Red
        Write-ServiceMessage 'buildProblem' @{ description = "No test archive applies to $Platform." }
        exit 1
    }

    $dotnet = $null

    if ($runs | Where-Object { $_.Manifest.Entry -like '*.dll' })
    {
        $dotnet = (Get-Command dotnet -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1).Source

        if (-not $dotnet)
        {
            Write-Host "The .NET runtime is needed by the .NET test applications, and 'dotnet' was not found." -ForegroundColor Red
            exit 1
        }

        $installedRuntimes = Get-InstalledRuntimes $dotnet
        $runs | ForEach-Object { $_.InstalledRuntimes = $installedRuntimes }
    }

    # Each package is found, downloaded and checked once, before the applications start, and not once per archive.
    $script:Packages = @{ }

    foreach ($package in @($runs | ForEach-Object { $_.Manifest.Packages }))
    {
        $packageKey = "$( $package.Id )/$( $package.Version )"

        if (-not $script:Packages.ContainsKey($packageKey))
        {
            $script:Packages[$packageKey] = Get-Package $package
        }
    }

    # The applications that must run alone run first, one at a time, while nothing else loads the machine.
    $failed += Invoke-TestRuns @( $runs | Where-Object { $_.Manifest.RunAlone } ) 1 $dotnet
    $failed += Invoke-TestRuns @( $runs | Where-Object { -not $_.Manifest.RunAlone } ) $MaxParallel $dotnet

    Write-Host ""
    Write-Host "$Platform : $( $runs.Count - @($failed | Where-Object { $runs.Key -contains $_ }).Count ) passed, $( $failed.Count ) failed, $ignored not run." -ForegroundColor Cyan

    if ($failed)
    {
        Write-Host "Failed: $( $failed -join ', ' )" -ForegroundColor Red
        exit 1
    }

    exit 0
}
finally
{
    Pop-Location
}
